const BACKEND='http://backend:3000';
const H=this.helpers;
const tz='America/Argentina/Buenos_Aires';
const login=await H.httpRequest({method:'POST',url:BACKEND+'/auth/login',headers:{'Content-Type':'application/json'},body:{email:'__ADMIN_EMAIL__',password:'__ADMIN_PASSWORD__'},json:true});
const token=login.token;
const t=new Date(Date.now()+24*60*60*1000);
const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(t).map(x=>[x.type,x.value]));
const fecha=p.year+'-'+p.month+'-'+p.day;
const reservas=await H.httpRequest({method:'GET',url:BACKEND+'/reservas?fecha='+fecha+'&estado=CONFIRMADA',headers:{authorization:'Bearer '+token},json:true});
const out=[];
for(const r of (reservas||[])){
  const number=String((r.cliente&&r.cliente.whatsapp)||'').replace(/[^0-9]/g,'');
  if(!number) continue;
  let hs=''; try{ hs=new Intl.DateTimeFormat('es-AR',{timeZone:tz,hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(r.fechaInicio)); }catch(e){}
  const canchaN=(r.cancha&&r.cancha.nombre)||'la cancha';
  out.push({ json:{ number, replyText:'Hola! Te recordamos tu turno de manana en '+canchaN+' a las '+hs+'hs. Te esperamos! Si no podes venir, avisanos.' } });
}
return out;
